#include <stdio.h>
#include <stdlib.h>

#define MAX(a,b) ((a) > (b) ? (a) : (b))

int* charStatistic(const char* s) {
    int* cnts = (int*) calloc(128, sizeof(int));

    int i = 0;
    while(s[i] != '\0') {
        cnts[s[i]]++;
        i++;
    }

    return cnts;
}

int main() {
    int n;
    scanf("%d", &n);

    char words[100][101];

    for (int i = 0; i < n; i++) {
        scanf("%s", words[i]);
    }

    char chars[101];
    scanf("%s", chars);

    // 记录题解
    int ans = 0;

    // 统计chars字符串中各字符的数量
    int* cnts_char = charStatistic(chars);

    for(int i=0; i<n; i++) {
        int diff = 0;

        // 统计word字符串中各字符的数量
        int* cnt_word = charStatistic(words[i]);

        for(int j=0; j<128; j++) {
            // 记录word的某字符超过chars的对应字符出现的数量
            diff += MAX(cnt_word[j] - cnts_char[j], 0);
        }

        if(diff <= cnts_char['?']) {
            ans++;
            // puts(words[i]);
        }
    }

    printf("%d\n", ans);
}
